recipes.code:
{
  "inputs": [
    {
      "id": "justfill-api-key",
      "type": "promptString",
      "description": "API key from justfill.app -> Account -> API Keys. Optional: `justfill-mcp login` stores one via the browser instead.",
      "password": true
    }
  ],
  "servers": {
    "justfill": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "justfill-mcp@0.4.7"
      ],
      "env": {
        "JUSTFILL_API_KEY": "${input:justfill-api-key}"
      }
    }
  }
}
